16	/**
17	 * A GraphQLError describes an Error found during the parse, validate, or
18	 * execute phases of performing a GraphQL operation. In addition to a message
19	 * and stack trace, it also includes information about the locations in a
20	 * GraphQL document and/or execution result that correspond to the Error.
21	 */
22	declare class GraphQLError extends Error {
23	  constructor(
24	    message: string,
25	    nodes?: $ReadOnlyArray<ASTNode> | ASTNode | void | null,
26	    source?: ?Source,
27	    positions?: ?$ReadOnlyArray<number>,
28	    path?: ?$ReadOnlyArray<string | number>,
29	    originalError?: ?Error,
30	    extensions?: ?{ [key: string]: mixed },
31	  ): void;
