41	
42	  /**
43	   * An array of { line, column } locations within the source GraphQL document
44	   * which correspond to this error.
45	   *
46	   * Errors during validation often contain multiple locations, for example to
47	   * point out two things with the same name. Errors during execution include a
48	   * single location, the field which produced the error.
49	   *
50	   * Enumerable, and appears in the result of JSON.stringify().
51	   */
52	  +locations: $ReadOnlyArray<SourceLocation> | void;
53	
54	  /**
55	   * An array describing the JSON-path into the execution response which
56	   * corresponds to this error. Only included for errors during execution.
57	   *
58	   * Enumerable, and appears in the result of JSON.stringify().
59	   */
60	  +path: $ReadOnlyArray<string | number> | void;
61	
62	  /**
63	   * An array of GraphQL AST Nodes corresponding to this error.
64	   */
65	  +nodes: $ReadOnlyArray<ASTNode> | void;
