194	  // Include (non-enumerable) stack trace.
195	  if (originalError && originalError.stack) {
196	    Object.defineProperty(this, 'stack', {
197	      value: originalError.stack,
198	      writable: true,
199	      configurable: true,
200	    });
201	  } else if (Error.captureStackTrace) {
202	    Error.captureStackTrace(this, GraphQLError);
203	  } else {
204	    Object.defineProperty(this, 'stack', {
205	      value: Error().stack,
206	      writable: true,
207	      configurable: true,
208	    });
209	  }
210	}
