212	(GraphQLError: any).prototype = Object.create(Error.prototype, {
213	  constructor: { value: GraphQLError },
214	  name: { value: 'GraphQLError' },
215	  toString: {
216	    value: function toString() {
217	      return printError(this);
218	    },
219	  },
220	});
